This is the standard shear/unipotent matrix multiplication identity. -/
theorem unipotentElem_mul_add (F : Type*) [Field F] (s t : F) :
    ((fun i j : Fin 2 =>
        if i = (0 : Fin 2) ∧ j = (0 : Fin 2) then (1 : F)
        else if i = (0 : Fin 2) ∧ j = (1 : Fin 2) then s
        else if i = (1 : Fin 2) ∧ j = (0 : Fin 2) then (0 : F)
        else (1 : F)) : Matrix (Fin 2) (Fin 2) F) *
      ((fun i j : Fin 2 =>
        if i = (0 : Fin 2) ∧ j = (0 : Fin 2) then (1 : F)
        else if i = (0 : Fin 2) ∧ j = (1 : Fin 2) then t
        else if i = (1 : Fin 2) ∧ j = (0 : Fin 2) then (0 : F)
        else (1 : F)) : Matrix (Fin 2) (Fin 2) F) =
      ((fun i j : Fin 2 =>
        if i = (0 : Fin 2) ∧ j = (0 : Fin 2) then (1 : F)
        else if i = (0 : Fin 2) ∧ j = (1 : Fin 2) then s + t
        else if i = (1 : Fin 2) ∧ j = (0 : Fin 2) then (0 : F)
